1	//! Fenced code block parsing for Markdown (CommonMark §4.5).
2	//!
3	//! A fenced code block begins with a code fence: at least three consecutive
4	//! backtick (`) or tilde (~) characters. It ends with a closing fence of at
5	//! least as many characters of the same type, or at the end of the document.
6	//!
7	//! # Examples
8	//!
9	//! ````markdown
10	//! ```rust
11	//! fn main() {}
12	//! ```
13	//!
14	//! ~~~python
15	//! def hello():
16	//!     pass
17	//! ~~~
18	//! ````
19	//!
20	//! # Info String
21	//!
22	//! The opening fence may be followed by an info string (language identifier)
23	//! that can be used for syntax highlighting.
24	
25	use crate::parser::MarkdownParser;
26	use crate::token_source::find_line_start;
27	use biome_markdown_syntax::{T, kind::MarkdownSyntaxKind::*};
28	use biome_parser::{
29	    Parser,
30	    prelude::{
31	        ParsedSyntax::{self, *},
32	        TokenSource,
33	    },
34	};
35	
36	use crate::syntax::parse_error::unterminated_fenced_code;
37	use crate::syntax::quote::try_bump_quote_marker;
38	use crate::syntax::{MAX_BLOCK_PREFIX_INDENT, TAB_STOP_SPACES};
39	
40	/// Minimum number of fence characters required per CommonMark §4.5.
41	const MIN_FENCE_LENGTH: usize = 3;
42	
43	/// Consume indent whitespace (spaces/tabs) from source bytes.
44	///
45	/// Tracks column width where tabs expand to next multiple of 4.
46	/// Returns `Some(new_idx)` on success, or `None` if required indent wasn't met.
47	fn consume_indent(source: &[u8], mut idx: usize, limit: usize, required: bool) -> Option<usize> {
48	    let mut column = 0usize;
49	    while column < limit {
50	        match source.get(idx).copied() {
51	            Some(b' ') => {
52	                column += 1;
53	                idx += 1;
54	            }
55	            Some(b'\t') => {
56	                let tab_width = TAB_STOP_SPACES - (column % TAB_STOP_SPACES);
57	                // For optional indent, don't exceed limit with tab
58	                if !required && column + tab_width > limit {
59	                    break;
60	                }
61	                column += tab_width;
62	                idx += 1;
63	            }
64	            _ => {
65	                if required {
66	                    return None;
67	                }
68	                break;
69	            }
70	        }
71	    }
72	    Some(idx)
73	}
74	
75	/// Get parser source context with bounds checking.
76	///
77	/// Returns `Some((start_position, source_text))` if the current position is valid,
78	/// or `None` if the position is out of bounds.
79	fn get_source_context<'a>(p: &'a MarkdownParser) -> Option<(usize, &'a str)> {
80	    let start: usize = p.cur_range().start().into();
81	    let source = p.source().text();
82	    if start > source.len() {
83	        return None;
84	    }
85	    Some((start, source))
86	}
87	
88	/// Check if the prefix from line_start to start is all whitespace.
89	///
90	/// Returns `true` if the prefix contains only spaces/tabs.
91	fn is_whitespace_prefix(source: &str, start: usize, line_start: usize) -> bool {
92	    source[line_start..start]
93	        .chars()
94	        .all(|c| c == ' ' || c == '\t')
95	}
96	
97	/// Bump a fence token (``` or ~~~), remapping if necessary.
98	fn bump_fence(p: &mut MarkdownParser, is_tilde_fence: bool) {
99	    if is_tilde_fence {
100	        if p.at(TRIPLE_TILDE) {
101	            p.bump(TRIPLE_TILDE);
102	        } else {
103	            p.bump_remap(TRIPLE_TILDE);
104	        }
105	    } else if p.at(T!["```"]) {
106	        p.bump(T!["```"]);
107	    } else {
108	        p.bump_remap(T!["```"]);
109	    }
110	}
111	
112	/// Detect a code fence at the start of a string.
113	///
114	/// Per CommonMark §4.5: "A code fence is a sequence of at least three
115	/// consecutive backtick characters (`) or tildes (~)."
116	///
117	/// Returns `Some((fence_char, length))` if a valid fence is found,
118	/// where `length` is the actual number of fence characters (3 or more).
119	/// Returns `None` if no valid fence is present.
120	pub(crate) fn detect_fence(s: &str) -> Option<(char, usize)> {
121	    let first_char = s.chars().next()?;
122	
123	    if first_char != '`' && first_char != '~' {
124	        return None;
125	    }
126	
127	    let len = s.chars().take_while(|&c| c == first_char).count();
128	
129	    if len >= MIN_FENCE_LENGTH {
130	        Some((first_char, len))
131	    } else {
132	        None
133	    }
134	}
135	
136	/// Check if we're at a fenced code block (``` or ~~~).
137	pub(crate) fn at_fenced_code_block(p: &mut MarkdownParser) -> bool {
138	    p.lookahead(|p| {
139	        if !p.at_start_of_input() && !is_line_start_within_indent(p, MAX_BLOCK_PREFIX_INDENT) {
140	            return false;
141	        }
142	        p.skip_line_indent(MAX_BLOCK_PREFIX_INDENT);
143	
144	        let rest = p.source_after_current();
145	        let Some((fence_char, _)) = detect_fence(rest) else {
146	            return false;
147	        };
148	        if fence_char == '`' && info_string_has_backtick(p) {
149	            return false;
150	        }
151	        true
152	    })
153	}
154	
155	/// Parse a fenced code block.
156	///
157	/// Grammar:
158	/// MdFencedCodeBlock =
159	///   indent: MdIndentTokenList
160	///   l_fence: ('```' | '~~~')
161	///   code_list: MdCodeNameList
162	///   content: MdInlineItemList
163	///   r_fence_indent: MdIndentTokenList
164	///   r_fence: ('```' | '~~~')
165	pub(crate) fn parse_fenced_code_block(p: &mut MarkdownParser) -> ParsedSyntax {
166	    parse_fenced_code_block_impl(p, false)
167	}
168	
169	pub(crate) fn parse_fenced_code_block_force(p: &mut MarkdownParser) -> ParsedSyntax {
170	    parse_fenced_code_block_impl(p, true)
171	}
172	
173	fn parse_fenced_code_block_impl(p: &mut MarkdownParser, force: bool) -> ParsedSyntax {
174	    if !force && !at_fenced_code_block(p) {
175	        return Absent;
176	    }
177	
178	    let m = p.start();
179	
180	    let mut fence_indent = p.line_start_leading_indent();
181	    if p.state().list_item_required_indent > 0
182	        && p.state().virtual_line_start == Some(p.cur_range().start())
183	    {
184	        fence_indent += p.state().list_item_required_indent;
185	    }
186	    p.emit_line_indent(MAX_BLOCK_PREFIX_INDENT);
187	
188	    // Detect fence type and length (must close with same type and >= length per CommonMark §4.5)
189	    let text = p.cur_text();
190	    let (fence_char, fence_len) = detect_fence(text).unwrap_or(('`', MIN_FENCE_LENGTH));
191	    let is_tilde_fence = fence_char == '~';
192	    let fence_type = if is_tilde_fence { "~~~" } else { "```" };
193	
194	    // Record opening fence range for diagnostic
195	    let opening_range = p.cur_range();
196	
197	    // Opening fence (``` or ~~~)
198	    bump_fence(p, is_tilde_fence);
199	
200	    // Optional language info string (MdCodeNameList)
201	    parse_code_name_list(p);
202	
203	    // Content (everything until closing fence)
204	    parse_code_content(p, is_tilde_fence, fence_len, fence_indent);
205	
206	    // Closing fence - emit specific diagnostic if missing
207	    // Must match the opening fence type
208	    let has_closing = at_closing_fence(p, is_tilde_fence, fence_len);
209	
210	    if has_closing {
211	        // Closing fence indent: strip list continuation indent plus the
212	        // CommonMark-allowed 0-3 spaces before the fence itself.
213	        let max = if p.state().list_item_required_indent > 0 {
214	            p.state().list_item_required_indent + MAX_BLOCK_PREFIX_INDENT
215	        } else {
216	            MAX_BLOCK_PREFIX_INDENT
217	        };
218	        p.emit_line_indent(max);
219	        bump_fence(p, is_tilde_fence);
220	    } else {
221	        // Emit diagnostic for unterminated code block
222	        p.error(unterminated_fenced_code(p, opening_range, fence_type));
223	        // Emit empty r_fence_indent list to satisfy grammar slot
224	        let empty_m = p.start();
225	        empty_m.complete(p, MD_INDENT_TOKEN_LIST);
