pub(crate) struct FormatMdCodeNameList;
impl FormatRule<MdCodeNameList> for FormatMdCodeNameList {
    type Context = MarkdownFormatContext;
    fn fmt(&self, node: &MdCodeNameList, f: &mut MarkdownFormatter) -> FormatResult<()> {
        // The info string (language/metadata following the opening fence) is
        // stored across one or more `MdTextual` tokens. Normalize it by
        // trimming any leading and trailing whitespace while preserving its
        // internal structure (commas and multiple space-separated values such
        // as `rust,  ignore   expect_diagnostics` must be kept intact).
        //
        // Trimming the leading whitespace also guarantees the info string is
        // emitted immediately after the opening fence characters, without any
        // separating space.
        let tokens: Vec<_> = node.syntax().tokens().collect();

        let Some(first) = tokens.first() else {
            return Ok(());
        };

        let raw = node.syntax().text_trimmed().to_string();
        let info = raw.trim();

        if info.is_empty() {
